using System.Numerics;
using LiteDB;
using PvpStats.Analysis;
internal static class ReplaySummonChecks {
    public static void Run(Action<bool,string> check) {
        var now=new DateTime(2026,10,17,0,0,0,DateTimeKind.Utc);
        var sample=new ReplaySummonFrame {Timestamp=now,Summons=new(){new(){EntityId=10,NameId=6566,Owner="Owner World",X=1,Y=0,Z=2}}};
        var frames=new[]{sample,new ReplaySummonFrame {Timestamp=now.AddSeconds(.2)}};
        check(ReplaySummons.At(frames,now.AddSeconds(-.01))==null,"summons never appear before their first observed sample");
        check(ReplaySummons.At(frames,now.AddSeconds(.1))==sample,"summons use the latest past loaded-object observation");
        check(ReplaySummons.At(frames,now.AddSeconds(.3))!.Summons.Count==0,"an observed empty sample stops a disappeared summon");
        check(ReplaySummons.At(new[]{sample},now.AddSeconds(.46))==null,"recording gaps never fabricate a full nominal summon lifetime");
        check(ReplaySummons.IsPetAction(29675)&&ReplaySummons.IsPetAction(29681)&&!ReplaySummons.IsPetAction(29665)&&!ReplaySummons.IsPetAction(29666),"only autonomous LB pet actions added, ordinary summoner follow-ups stay excluded");
        var scene=new ReplaySceneGeometry();ReplaySummons.Draw(scene,sample,Array.Empty<ReplaySkillEvent>(),null,now,(_,y,_)=>y);
        var baseline=scene.Vertices.Length;
        check(baseline>0&&scene.Vertices.ToArray().Any(v=>v.Position.Y>6),"observed pet has an airborne placeholder");
        check(scene.Vertices.ToArray().Where(v=>v.Position.Y<1).All(v=>Vector2.Distance(new(v.Position.X,v.Position.Z),new(1,2))<30.2),"selection waves stay within the official 30y radius");
        var effect=new ReplaySkillEvent {Timestamp=now,ActionId=29676,SourceEntityId=10,PetSource=true,Resolved=true,SummonTargets=new(){new(){Player="Hit World",X=8,Y=0,Z=9}}};
        scene.Clear();ReplaySummons.Draw(scene,sample,new[]{effect},null,now.AddSeconds(.1),(_,y,_)=>y);var linked=scene.Vertices.Length;
        scene.Clear();ReplaySummons.Draw(scene,sample,Array.Empty<ReplaySkillEvent>(),null,now.AddSeconds(.1),(_,y,_)=>y);
        check(linked==scene.Vertices.Length+12,"only recorded summon hits create target links");
        effect.SourceEntityId=11;scene.Clear();ReplaySummons.Draw(scene,sample,new[]{effect},null,now.AddSeconds(.1),(_,y,_)=>y);
        check(scene.Vertices.Length==linked-12,"different summon entities never inherit one another's targets");
        effect.SourceEntityId=10;effect.Timestamp=now.AddSeconds(1);scene.Clear();ReplaySummons.Draw(scene,sample,new[]{effect},null,now.AddSeconds(.1),(_,y,_)=>y);
        check(scene.Vertices.Length==linked-12,"future hit packets cannot leak into replay links");
        effect.Timestamp=now;effect.SummonTargets[0].Benefit=true;
        scene.Clear();ReplaySummons.Draw(scene,sample,new[]{effect},null,now.AddSeconds(.1),(_,y,_)=>y);
        var linkColor=scene.Vertices.ToArray()[^1].Color;
        check(((linkColor>>8)&255)>(linkColor&255),"recorded healing links are mint green rather than player blue/red");
        scene.Clear();ReplaySummons.Draw(scene,sample,new[]{effect},null,now.AddSeconds(1.3),(_,y,_)=>y);var expired=scene.Vertices.Length;
        scene.Clear();ReplaySummons.Draw(scene,sample,Array.Empty<ReplaySkillEvent>(),null,now.AddSeconds(1.3),(_,y,_)=>y);
        check(scene.Vertices.Length==expired,"summon effect links fade out rather than accumulating throughout the match");
        var root=new ReplaySkillEvent {Timestamp=now,ActionId=29673,Actor="Owner World",GroundX=12,GroundY=2,GroundZ=18};
        var resolved=ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{root},now.AddSeconds(5));
        check(resolved.Summons.Count==1&&resolved.Summons[0].Estimated&&resolved.Summons[0].X==12,"recorded LB ground placement displays a placeholder even without recognized NPC or owner objects");
        scene.Clear();ReplaySummons.Draw(scene,resolved,new[]{root},null,now.AddSeconds(5),(_,y,_)=>y);
        check(scene.Vertices.Length>500,"root-only legacy recording produces an actual placeholder and continuous waves in the render geometry");
        check(ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{root},now.AddSeconds(-.1)).Summons.Count==0,"fallback summon never appears before the recorded LB");
        check(ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{root},now.AddSeconds(20)).Summons.Count==0,"estimated LB placeholder expires after official 20s instead of persisting forever");
        var impact=new ReplaySkillEvent {Timestamp=now.AddSeconds(.4),ActionId=29673,Actor=root.Actor,GroundX=12,GroundY=2,GroundZ=18,Resolved=true};
        check(ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{root,impact},now.AddSeconds(20.1)).Summons.Count==0,"use and impact packets do not extend estimated summon duration");
        var missingGround=new ReplaySkillEvent {Timestamp=now,ActionId=29673,Actor="Other World",X=99,Z=99};
        check(ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{missingGround},now.AddSeconds(1)).Summons.Count==0,"unknown ground placement is never replaced by caster position or origin");
        var unowned=new ReplaySkillEvent {Timestamp=now,ActionId=29676,SourceEntityId=88,X=6,Y=2,Z=3,Resolved=true};
        var unownedResult=ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{unowned},now.AddSeconds(.1));
        check(unownedResult.Summons.Count==1&&unownedResult.Summons[0].EntityId==88,"autonomous action identifies a summon without readable owner or hard-coded NPC name ID");
        check(ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{unowned},now.AddSeconds(1.1)).Summons.Count==0,"one ownerless effect does not invent a full summon lifetime");
        var placedRoot=new ReplaySkillEvent {Timestamp=now.AddSeconds(-1),ActionId=29673,Actor="Owner World",GroundX=6,GroundY=2,GroundZ=3};
        var combined=ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{placedRoot,unowned},now.AddSeconds(.1));
        check(combined.Summons.Count==1&&combined.Summons[0].EntityId==88,"unique unowned physical source merges with matching LB placement instead of drawing duplicate ghost summons");
        var observedRoot=new ReplaySkillEvent {Timestamp=now.AddSeconds(-1),ActionId=29673,Actor="Owner World",GroundX=1,GroundY=0,GroundZ=2};
        check(ReplaySummons.Resolve(frames,new[]{observedRoot},now.AddSeconds(.3)).Summons.Count==0,"positive object disappearance overrides estimated root lifetime");
        check(ReplaySummons.Resolve(frames,new[]{observedRoot},now.AddSeconds(5)).Summons.Count==0,"confirmed disappearance remains stopped when the empty sample ages beyond freshness");
        check(ReplaySummons.Resolve(new[]{frames[1]},new[]{observedRoot},now.AddSeconds(.3)).Summons.Count==1,"unidentified empty object scan cannot suppress a known LB placeholder");
        var phoenix=new ReplaySkillEvent {Timestamp=now.AddSeconds(2),ActionId=29678,Actor=root.Actor,GroundX=14,GroundY=2,GroundZ=18};
        var replacement=ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),new[]{root,phoenix},now.AddSeconds(3));
        check(replacement.Summons.Count==1&&replacement.Summons[0].Phoenix,"new Phoenix replaces same owner's prior Bahamut placeholder");
        var legacyData=new DetailedTelemetry {Frames=new(){new(){Timestamp=now.AddSeconds(1),Players=new(){new(){Player="Hit World",X=7,Y=0,Z=8}}}},
            Effects=new(){new(){Timestamp=now.AddSeconds(1),Actor=root.Actor,Target="Hit World",ActionId=29676,PetSource=true,Type=3,Sequence=9}}};
        var recovered=new List<ReplaySkillEvent>{root};ReplaySummons.RecoverEffects(legacyData,recovered);
        check(recovered.Count==2&&recovered[1].SummonTargets.Count==1&&recovered[1].LegacyEstimate,"old recorded pet effects recover real targets using recorded LB ground rather than fabricated source positions");
        var legacyScene=new ReplaySceneGeometry();var legacyResolved=ReplaySummons.Resolve(Array.Empty<ReplaySummonFrame>(),recovered,now.AddSeconds(1.1));
        ReplaySummons.Draw(legacyScene,legacyResolved,recovered,null,now.AddSeconds(1.1),(_,y,_)=>y);
        var legacyLinked=legacyScene.Vertices.Length;legacyScene.Clear();ReplaySummons.Draw(legacyScene,legacyResolved,new[]{root},null,now.AddSeconds(1.1),(_,y,_)=>y);
        check(legacyLinked==legacyScene.Vertices.Length+12,"recovered old pet effect reaches the rendered link even without source entity ID");
        var floorScene=new ReplaySceneGeometry();ReplaySummons.Draw(floorScene,sample,Array.Empty<ReplaySkillEvent>(),null,now,(_,_,_)=>4);
        check(floorScene.Vertices.ToArray().Where(v=>v.Position.Y<6).All(v=>v.Position.Y>=4),"wave geometry follows supplied terrain height instead of sinking below the map");
        var vertical=new ReplaySceneGeometry();vertical.Beam(new(1,6,2),new(1,1,2),.24f,0xffffffff);
        check(vertical.Vertices.Length>0&&vertical.Vertices.ToArray().All(v=>LimitBreakVisuals.Finite(v.Position)),"a summon directly above its target still produces a visible finite vertical beam");
        var doc=BsonMapper.Global.ToDocument(sample);var restored=BsonMapper.Global.ToObject<ReplaySummonFrame>(doc);
        check(restored.Summons[0].EntityId==10&&restored.Summons[0].Owner=="Owner World","summon position and owner round-trip storage");
        check(BsonMapper.Global.ToObject<DetailedTelemetry>(new BsonDocument()).SummonFrames.Count==0,"old matches without summon observations remain readable");
    }
}
